	"testing"
)

func TestHandle(t *testing.T) {
	t.Run("basic", func(t *testing.T) {
		c := httptest.NewServer(http.HandlerFunc(handle))
		defer c.Close()

		_, err := c.Get(c.URL)
		if err != nil {
			t.Fatalf("unexpected error: %v", err)
